import React, { useState, useEffect } from "react";
import {
  Box,
  Grid,
  Button,
  Container,
  Paper,
  TextField,
  Typography,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  IconButton,
  CircularProgress,
  Snackbar,
  Alert,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle,
} from "@mui/material";
import { db, collection, getDocs, updateDoc, deleteDoc, doc, onSnapshot, query, orderBy } from "../firebase/firebaseConfig";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";
import "../css/AddItem.css";  // Importing the CSS for responsiveness
import { Timestamp } from "firebase/firestore";

const EditItem = () => {
  const [items, setItems] = useState([]);
  const [filteredItems, setFilteredItems] = useState([]);  // For search filtering
  const [categories, setCategories] = useState([]);
  const [selectedItem, setSelectedItem] = useState(null); // To hold the item being edited
  const [loading, setLoading] = useState(false);
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [formError, setFormError] = useState("");
  const [selectedId, setSelectedId] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");  // For search input
  const [page, setPage] = useState(0);  // Current page
  const [rowsPerPage, setRowsPerPage] = useState(5);  // Items per page
  const [snackbarMessage, setSnackbarMessage] = useState("");
  const [open, setOpen] = useState(false);
  const userData = JSON.parse(localStorage.getItem("authUser"))

  useEffect(() => {
    // Fetch categories (one-time load)
    const fetchCategories = async () => {
      const categoriesRef = collection(db, "menuitemscategory");
      const querySnapshot = await getDocs(categoriesRef);
      const categoriesList = querySnapshot.docs.map((doc) => ({
        catID: doc.data().catID,
        catName: doc.data().catName,
      }));
      setCategories(categoriesList);
    };

    // Fetch items with real-time updates
    const fetchItems = () => {
      const itemsRef = query(collection(db, "menuitems"), orderBy("day", "asc"));

      // Listen for real-time updates
      const unsubscribe = onSnapshot(itemsRef, (querySnapshot) => {
        const itemsList = querySnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setItems(itemsList);
        // console.log(itemsList)
        setFilteredItems(itemsList); // Initially no filter applied
      });

      // Return unsubscribe function for cleanup
      return unsubscribe;
    };

    fetchCategories();
    const unsubscribeItems = fetchItems();

    return () => {
      unsubscribeItems(); // Cleanup listener on component unmount
    };
  }, []);

  const handleItemChange = (field, value) => {

    setSelectedItem({ ...selectedItem, [field]: value });
  };

  const validateForm = () => {
    if (!selectedItem.itemName || !selectedItem.itemDesc || !selectedItem.price || !selectedItem.catID) {
      setFormError("All fields must be filled before submitting.");
      alert(formError)
      return false;
    }
    setFormError("");
    return true;
  };

  const handleSubmit = async () => {
    const userDetails = JSON.parse(localStorage.getItem("authUser"));

    if (!validateForm()) return;
    ////console.log('in')
    setLoading(true);
    const catName = categories.find(e => e.catID === selectedItem.catID)?.catName || "";

    console.log(selectedItem)
    try {
      const itemDoc = doc(db, "menuitems", selectedItem.id);
      await updateDoc(itemDoc, {
        itemName: selectedItem.itemName,
        itemDesc: selectedItem.itemDesc,
        price: parseFloat(selectedItem.price),
        catID: selectedItem.catID,
        catName: catName,
        available: selectedItem.available,
        day: selectedItem.day,
        updatedAt: Timestamp.now(),
        updatedBy: userDetails.userName
      });

      setSnackbarOpen(true);
      setSnackbarMessage("Item Updated successfully!");
      setSelectedItem(null); // Reset the selected item after update
    } catch (error) {
      console.error("Error updating item:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleOpen = (id) => {
    setSelectedId(id);
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setSelectedId(null);
  };

  const handleDelete = async () => {
    if (!selectedId) return;

    try {
      await deleteDoc(doc(db, "menuitems", selectedId));
      setItems(items.filter((item) => item.id !== selectedId));
      setFilteredItems(filteredItems.filter((item) => item.id !== selectedId));

      // Set Snackbar message for delete action
      setSnackbarMessage("Item deleted successfully!");
      setSnackbarOpen(true);
    } catch (error) {
      console.error("Error deleting item:", error);
    }

    handleClose();
  };

  const handleEdit = (item) => {
    setSelectedItem({ ...item });
  };

  const handleSearch = (event) => {
    const query = event.target.value.toLowerCase();
    setSearchQuery(query);

    // Filter items based on the search query
    const filtered = items.filter(item => {
      const dayName = getDayName(item.day).toLowerCase();
      const price = item.price.toString().toLowerCase();
      const available = item.available ? "yes" : "no";

      return (
        item.itemName.toLowerCase().includes(query) ||
        item.itemDesc.toLowerCase().includes(query) ||
        dayName.includes(query) ||
        price.includes(query) ||
        item.catName.toLowerCase().includes(query) ||
        available.includes(query)
      );
    });

    setFilteredItems(filtered);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0); // Reset to first page when rows per page changes
  };

  const getDayName = (dayIndex) => {
    const days = ["All Time Available", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
    return days[dayIndex] || "Unknown";
  };

  return (
    <Container
      sx={{
        maxWidth: {
          xs: "100%",
          sm: "600px",
          md: "800px",
          lg: "1000px",
        }, mt: 2, mb: 1

      }}
      className="container"
    >
      <Paper elevation={4} sx={{ p: 1, mt: 0, borderRadius: 1, width: '100%', color: ' #3f51b5' }} className="paper">
        <Typography variant="h5" gutterBottom>
          Edit Menu Items
        </Typography>

        {/* Search Field */}
        <TextField
          fullWidth
          label="Search Items"
          value={searchQuery}
          onChange={handleSearch}
          sx={{ mb: 2 }}
        />

        {/* Table for Existing Items */}
        <TableContainer component={Paper} sx={{ mb: 2, width: '100%', overflowX: 'auto' }} className="table-container">
          <Table>
            <TableHead>
              <TableRow>
                <TableCell sx={{ padding: { xs: '6px 8px', sm: '8px 16px' }, fontSize: { xs: '0.90rem', sm: '1rem' } }}>Day</TableCell>
                <TableCell sx={{ padding: { xs: '6px 8px', sm: '8px 16px' }, fontSize: { xs: '0.90rem', sm: '1rem' } }}>Item Name</TableCell>
                {/* Hide Category column on xs screen */}
                <TableCell sx={{ padding: { xs: '6px 8px', sm: '8px 16px' }, fontSize: { xs: '0.90rem', sm: '1rem' }, display: { xs: 'none', sm: 'table-cell' } }}>Category</TableCell>
                {/* Hide Available column on xs screen */}
                <TableCell sx={{ padding: { xs: '6px 8px', sm: '8px 16px' }, fontSize: { xs: '0.90rem', sm: '1rem' }, display: { xs: 'none', sm: 'table-cell' } }}>Available</TableCell>
                <TableCell sx={{ padding: { xs: '6px 8px', sm: '8px 16px' }, fontSize: { xs: '0.90rem', sm: '1rem' } }}>Price</TableCell>
                <TableCell sx={{ padding: { xs: '6px 8px', sm: '8px 16px' }, fontSize: { xs: '0.90rem', sm: '1rem' } }}>
                  {userData?.role === 1 || userData?.role === 2 ? (
                    "Action"
                  ) : null}
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredItems.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((item) => (
                <TableRow key={item.id}>
                  <TableCell sx={{ fontSize: { xs: '0.90rem', sm: '1rem' }, padding: { xs: '6px 8px', sm: '8px 16px' } }}>
                    {getDayName(item.day)}
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.90rem', sm: '1rem' }, padding: { xs: '6px 8px', sm: '8px 16px' } }}>
                    {item.itemName}
                  </TableCell>
                  {/* Hide Category column on xs screen */}
                  <TableCell sx={{ fontSize: { xs: '0.90rem', sm: '1rem' }, padding: { xs: '6px 8px', sm: '8px 16px' }, display: { xs: 'none', sm: 'table-cell' } }}>
                    {item.catName}
                  </TableCell>
                  {/* Hide Available column on xs screen */}
                  <TableCell sx={{ fontSize: { xs: '0.90rem', sm: '1rem' }, padding: { xs: '6px 8px', sm: '8px 16px' }, display: { xs: 'none', sm: 'table-cell' } }}>
                    {item.available ? "Yes" : "No"}
                  </TableCell>
                  <TableCell sx={{ fontSize: { xs: '0.90rem', sm: '1rem' }, padding: { xs: '6px 8px', sm: '8px 16px' } }}>
                    {item.price}
                  </TableCell>
                  <TableCell sx={{ padding: { xs: '6px 8px', sm: '8px 16px' } }}>
                    {(userData?.role == 1 || userData?.role == 2) && (
                      <>
                        <IconButton onClick={() => handleEdit(item)}>
                          <EditIcon color="primary" />
                        </IconButton>
                        <IconButton onClick={() => handleOpen(item.id)}>
                          <DeleteIcon color="error" />
                        </IconButton>
                      </>
                    )}
                  </TableCell>

                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {/* Pagination */}
        <TablePagination
          rowsPerPageOptions={[5, 10, 25]}
          component="div"
          count={filteredItems.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          sx={{
            '& .MuiTablePagination-selectLabel': {
              fontSize: { xs: '0.90rem', sm: '1rem' }, // Adjust font size for smaller screens
            },
            '& .MuiTablePagination-select': {
              fontSize: { xs: '0.90rem', sm: '1rem' }, // Adjust select box font size for smaller screens
            },
            '& .MuiTablePagination-actions': {
              fontSize: { xs: '0.90rem', sm: '1rem' }, // Adjust pagination buttons for smaller screens
            },
            '& .MuiTablePagination-toolbar': {
              padding: { xs: '6px 8px', sm: '8px 16px' }, // Adjust padding for smaller screens
            },
          }}
        />
        <Dialog open={open} onClose={handleClose}>
          <DialogTitle>Confirm Delete</DialogTitle>
          <DialogContent>
            <DialogContentText>
              Are you sure you want to delete this item? This action cannot be undone.
            </DialogContentText>
          </DialogContent>
          <DialogActions>
            <Button onClick={handleClose} color="primary">Cancel</Button>
            <Button onClick={handleDelete} color="error" autoFocus>Delete</Button>
          </DialogActions>
        </Dialog>
        <Snackbar open={snackbarOpen} autoHideDuration={3000} onClose={() => setSnackbarOpen(false)}>
          <Alert severity="success" onClose={() => setSnackbarOpen(false)}>
            {snackbarMessage}
          </Alert>
        </Snackbar>
        {/* Form for Editing Item */}
        {selectedItem && (
          <Paper sx={{ p: 2, borderRadius: 2, width: '100%' }}>
            <Grid container spacing={2}>
              {/* Item Name */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Item Name"
                  value={selectedItem.itemName}
                  onChange={(e) => handleItemChange("itemName", e.target.value)}
                />
              </Grid>

              {/* Item Description */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Item Description"
                  value={selectedItem.itemDesc}
                  onChange={(e) => handleItemChange("itemDesc", e.target.value)}
                />
              </Grid>

              {/* Price */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Price"
                  type="number"
                  value={selectedItem.price}
                  onChange={(e) => handleItemChange("price", e.target.value)}
                />
              </Grid>

              {/* Category */}
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth>
                  <InputLabel>Category</InputLabel>
                  <Select
                    value={selectedItem.catID || ""}
                    onChange={(e) => handleItemChange("catID", e.target.value)}
                  >
                    {categories.map((cat) => (
                      <MenuItem key={cat.catID} value={cat.catID}>
                        {cat.catName}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>

              {/* Available */}
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth>
                  <InputLabel>Available</InputLabel>
                  <Select
                    value={selectedItem.available.toString()}
                    onChange={(e) => handleItemChange("available", e.target.value === "true")}
                  >
                    <MenuItem value="true">Yes</MenuItem>
                    <MenuItem value="false">No</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              {/* Day */}
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth>
                  <InputLabel>Day</InputLabel>
                  <Select
                    value={selectedItem.day}
                    onChange={(e) => handleItemChange("day", Number(e.target.value))}
                  >
                    <MenuItem value={0}>All Time Available</MenuItem>
                    <MenuItem value={1}>Monday</MenuItem>
                    <MenuItem value={2}>Tuesday</MenuItem>
                    <MenuItem value={3}>Wednesday</MenuItem>
                    <MenuItem value={4}>Thursday</MenuItem>
                    <MenuItem value={5}>Friday</MenuItem>
                    <MenuItem value={6}>Saturday</MenuItem>
                    <MenuItem value={7}>Sunday</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
            </Grid>

            {/* Submit and Cancel Buttons */}
            <Box sx={{ textAlign: "right", mt: 3 }}>
              <Button
                variant="contained"
                color="primary"
                onClick={handleSubmit}
                disabled={loading}
              >
                {loading ? <CircularProgress size={24} /> : "Update Item"}
              </Button>
              <Button
                variant="outlined"
                color="secondary"
                onClick={() => setSelectedItem(null)} // Cancel the editing
                sx={{ ml: 2 }}
              >
                Cancel
              </Button>
            </Box>
          </Paper>
        )}

        {/* Snackbar Notification */}

      </Paper>
    </Container>
  );
};

export default EditItem;
