import React, { useState, useEffect, useContext } from "react";
import {
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  CircularProgress,
  TablePagination,
  Snackbar,
  Dialog, DialogTitle, DialogContent, DialogContentText, DialogActions, Tooltip,
  
  Alert,
} from "@mui/material";


import { Check, DoneAll, Cancel } from "@mui/icons-material";
import { useParams } from "react-router-dom";
import { db, collection, query, where, getDocs, updateDoc, doc ,setDoc,orderBy,getDoc,onSnapshot} from "../firebase/firebaseConfig";
import dayjs from "dayjs";
import { Timestamp } from "firebase/firestore";

export default function OrderPage() {

  const { category } = useParams();
  const [orders, setOrders] = useState([]);
  const [open, setOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [updating, setUpdating] = useState(false);
  const [snackbar, setSnackbar] = useState({ open: false, message: "", severity: "success" });
  const [openConfirmDialog, setOpenConfirmDialog] = useState(false);
  const [pendingUpdate, setPendingUpdate] = useState(null);
  const handleOpen = ( item) => {
    console.log(item)
    setSelectedItem({ ...item, userName: item.userName, orderId: item.id ,remark:item.Remarks,timestamp:item.timestamp});
// console.log(item)
    setOpen(true);
  };
  const formatTime = (timestamp) => {
    if (!timestamp || !timestamp.seconds) return "";
    const date = new Date(timestamp.seconds * 1000); // Convert Firestore timestamp to JS Date
    return date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }); // 24-hour format
  };
  
  useEffect(() => {
    setPage(0); // Reset pagination when category changes
  }, [ orders]); 
  
  const handleClose = () => {
    setOpen(false);
    setSelectedItem(null);
  };
  useEffect(() => {
    const todayStart = Timestamp.fromDate(dayjs().startOf('day').toDate());
    const todayEnd = Timestamp.fromDate(dayjs().endOf('day').toDate());

    const today = new Date();
    const formattedToday = `${String(today.getDate()).padStart(2, "0")}-${String(today.getMonth() + 1).padStart(2, "0")}-${today.getFullYear()}`;

    console.log("Today's Date:", formattedToday); // Debugging output

    // Firestore query to fetch meetings on or after today
    const ordersQuery = query(
      collection(db, "meetingOrders"),
      where("MeetingDate", "==", formattedToday) // Fetch only today’s meetings
  );
    const itemsQuery = query(collection(db, 'menuitems'), where('available', '==', true));

    const unsubscribeOrders = onSnapshot(ordersQuery, (ordersSnapshot) => {
        let ordersData = ordersSnapshot.docs.map((doc) => ({
            id: doc.id,
            ...doc.data(),
        }));
console.log(ordersData)
        const unsubscribeItems = onSnapshot(itemsQuery, (itemsSnapshot) => {
            const menuItemsMap = itemsSnapshot.docs.map((doc) => ({
                id: doc.id,
                ...doc.data(),
            }));

            // Convert array to Map for easier lookup
            const menuItemsLookup = new Map(
                menuItemsMap.map((item) => [item.itemId, item]) // Ensure item.id is used correctly
            );

            const flattenedOrders = ordersData.flatMap((order) => {
                return (order.OrderItems || []).map((item) => {
                    const menuItem = menuItemsLookup.get(item.itemId);

                    return {
                        orderId: order.id,
                        itemId: item.itemId,
                        itemName: menuItem ? menuItem.itemName : "Unknown Item", // Extract only itemName
                        title: order.title || "Untitled",
                        userName: order.creatorName || "Unknown",
                        timestamp: order.CreatedAt || null,
                        statusCode: item.statusCode,
                        catName: menuItem.catName,
                        quantity:item.quantity,
                        MeetingDate:order.MeetingDate,
                        MeetingEndTime:order.MeetingEndTime,
                        MeetingStartTime:order.MeetingStartTime,
                        department:order.department,
                        employeeCode:order.employeeCode,
                        numPeople:order.numPeople,
                        title:order.title,
                        itemDeliverTime:item.Time

                    };
                });
            });

            // console.log(flattenedOrders);

            const filteredOrders = flattenedOrders
                // .filter((item) => item.catName === category)
                .sort((a, b) => {
                    const order = [1, 0, 3, 2];
                    const statusCodeSort = order.indexOf(a.statusCode) - order.indexOf(b.statusCode);

                    if (statusCodeSort !== 0) {
                        return statusCodeSort;
                    }

                    const timestampA = a.timestamp ? a.timestamp.toDate() : new Date(0);
                    const timestampB = b.timestamp ? b.timestamp.toDate() : new Date(0);

                    return timestampA - timestampB;
                });

            setOrders(filteredOrders);
            setLoading(false);
        });

        return () => unsubscribeItems();
    });

    return () => unsubscribeOrders();
}, []);

  
  
  

  
  
  const handleConfirmUpdate = async () => {
    if (pendingUpdate) {
     setOpenConfirmDialog(false);
     setPendingUpdate(null);
      await updateOrderItemStatusConfirmed(
        pendingUpdate.orderId,
        pendingUpdate.itemId,
        pendingUpdate.newStatus
      );
    }

  };
  
  const handleCancelUpdate = () => {
    setOpenConfirmDialog(false);
    setPendingUpdate(null);
  };
  
  const updateOrderItemStatus = async (orderId,  itemId, newStatus) => {
    if (newStatus === 2) {
      setPendingUpdate({ orderId,  itemId, newStatus });

      setOpenConfirmDialog(true);
      return;
    }
    await updateOrderItemStatusConfirmed(orderId,  itemId, newStatus);
  };
  
  const updateOrderItemStatusConfirmed = async (orderId, itemId, newStatus) => {
    // console.log(orderId, itemId, newStatus);
    try {
      setLoading(true);
  
      const orderRef = doc(db, "meetingOrders", orderId);
      const orderSnap = await getDoc(orderRef);
  
      if (!orderSnap.exists()) {
        console.error("Order not found");
        return;
      }
  
      const orderData = orderSnap.data();
  
      // Update only the statusCode for the matching itemId
      const updatedOrderItems = orderData.OrderItems.map((item) => {
        if (item.itemId === itemId) {
          return { ...item, statusCode: newStatus };
        }
        return item;
      });
  
      const userDetails = JSON.parse(localStorage.getItem("authUser"));
  
      await updateDoc(orderRef, {
        OrderItems: updatedOrderItems, // Ensure this matches Firestore field name
        updatedBy: userDetails?.userName || "Unknown",
        updatedAt: Timestamp.now(),
      });
  
      setSnackbar({ open: true, message: "Order status updated successfully!", severity: "success" });
    } catch (error) {
      console.error("Error updating order item status:", error);
      setSnackbar({ open: true, message: "Failed to update order status!", severity: "error" });
    } finally {
      setLoading(false);
    }
  };
  

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0); 
  };
  
  return (
    <div style={{ padding: "1px", position: "relative" }}>
    <Typography
      variant="h5"
      sx={{
        textAlign: "center",
        mt:0,
        fontWeight: "bold",
        textTransform: "capitalize",
        marginBottom: 0.4,
        color:'#3f51b5',
        
      }}
    >
     Meeting Orders
    </Typography>
  
    {loading ? (
      <div style={{ display: "flex", justifyContent: "center", alignItems: "center", height: "300px" }}>
        <CircularProgress />
      </div>
    ) : (
<TableContainer component={Paper} sx={{ display: 'flex',  alignItems: 'center', width: '100%', overflowX: 'auto', paddingRight: '0px', paddingLeft: '0px' }}>
  <Table sx={{width:'100%'}}>
    <TableHead>
      <TableRow sx={{ backgroundColor: '#f5f5f5', height: '50px' }}>
        {['Employee Name', 'Order Item', 'Qty.', 'Delivery At','Status'].map((header) => (
          <TableCell key={header} sx={{ fontWeight: '500', fontSize: '1rem', padding: '5px', backgroundColor: '#3f51b5', color: '#fff' }}>
            {header}
          </TableCell>
        ))}
      </TableRow>
    </TableHead>
    <TableBody>
      {orders.length === 0 ? (
        <TableRow sx={{ height: '50px' }}>
          <TableCell colSpan={5} align="center" sx={{ py: 2 }}>
            No orders found
          </TableCell>
        </TableRow>
      ) : (
        orders.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((item, index) => (
          <TableRow key={`${item.orderId}-${index}`} sx={{ height: '50px' }}>
            <TableCell sx={{
              fontWeight: 'bold',
              textTransform: 'capitalize',
              padding: '4px',
              borderRight: '1px solid #3f51b5',

            }}>
              
                <Typography >{item.userName}</Typography>
           
            </TableCell>

            <TableCell sx={{
              cursor: 'pointer',
              fontSize: '0.4rem',

              padding: '4px',
              borderRight: '1px solid #3f51b5',

            }} onClick={() => handleOpen( item)}>
            
                <Typography>{item.itemName}</Typography>
         
            </TableCell>

            <TableCell sx={{ fontSize: '1.1rem', verticalAlign: 'middle',textAlign:'center', padding: '4px', borderRight: '1px solid #3f51b5' }}>
              {item.quantity}
            </TableCell>
            <TableCell sx={{ fontSize: '1rem', verticalAlign: 'middle',textAlign:'center', padding: '4px', borderRight: '1px solid #3f51b5' }}>
            {item.itemDeliverTime}
            </TableCell>

            <TableCell sx={{
              padding: '0px',
             
              borderRight: '1px solid #3f51b5',
            }}>
              <div style={{display:'flex',gap:'3px',}}>
              {item.statusCode === 0 && (
                <Button onClick={() => updateOrderItemStatus(item.orderId, item.itemId, 1)} sx={{padding: '0px 0px',minWidth:'40px',marginLeft:'10px'}} disabled={updating}>
                  <Check color="success" sx={{ fontSize: '2.4rem',padding: '0px 0px', }} />
                </Button>
              )}
              {item.statusCode === 1 && (
                <Button onClick={() => updateOrderItemStatus(item.orderId, item.itemId, 3)} sx={{padding: '0px 0px',minWidth:'40px',marginLeft:'10px'}}  disabled={updating}>
                  <DoneAll color="success" sx={{ fontSize: '2.4rem',padding: '0px 0px', }} />
                </Button>
              )}
              {item.statusCode !== 2 && item.statusCode !== 3 && (
                <Button sx={{ padding: '0px 0px', minWidth:'40px'}} onClick={() => updateOrderItemStatus(item.orderId, item.itemId, 2)}  disabled={updating}>
                  <Cancel color="error" sx={{ fontSize: '1rem' }} />
                </Button>
              )}
              </div>
              {item.statusCode === 2 && (
                <Button disabled style={{ color: 'red', fontWeight: '800', fontSize: '0.8rem', margin: 0,  }}>
                  Cancelled
                </Button>
              )}
              {item.statusCode === 3 && (
                <Button disabled style={{ color: 'green', fontWeight: '800', fontSize: '0.8rem', margin: 0,  }}>
                  Delivered
                </Button>
              )}
            </TableCell>
          </TableRow>
        ))
      )}
    </TableBody>
  </Table>
</TableContainer>

    )}

<TablePagination
  rowsPerPageOptions={[10, 25,50,100]}
  component="div"
  count={orders.length} // Total number of flattened items
  rowsPerPage={rowsPerPage}
  page={page}
  onPageChange={handleChangePage}
  onRowsPerPageChange={handleChangeRowsPerPage}
/>


    <Snackbar open={snackbar.open} autoHideDuration={3000} onClose={() => setSnackbar({ ...snackbar, open: false })}>
      <Alert severity={snackbar.severity}>{snackbar.message}</Alert>
    </Snackbar>
  
    <Dialog open={openConfirmDialog} onClose={handleCancelUpdate}>
      <DialogTitle>Confirm Order Status Update</DialogTitle>
      <DialogContent>
        <DialogContentText>Are you sure?</DialogContentText>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleConfirmUpdate} color="primary">
          Yes
        </Button>
        <Button onClick={handleCancelUpdate} color="secondary">
          No
        </Button>
      </DialogActions>
    </Dialog>
  
    <Dialog open={open} onClose={handleClose}>
      <DialogTitle sx={{padding:1,margin:'15px'}}> Order Item Details</DialogTitle>
      <DialogContent>
        {selectedItem && (
          <>
            <Typography>
              <strong>Employee Name:</strong> {selectedItem.userName}
            </Typography>
            <Typography>
              <strong>Employee Department:</strong> {selectedItem.department}
            </Typography>
            <Typography>
              <strong>Meeting Date:</strong> {selectedItem.MeetingDate}
            </Typography>
            <Typography>
              <strong>Item Name:</strong> {selectedItem.itemName}
            </Typography>
            <Typography>
              <strong>Quantity:</strong> {selectedItem.quantity}
            </Typography>
            <Typography>
  <strong>Order Delivery Time:</strong> {selectedItem.itemDeliverTime}
</Typography>
          </>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} color="primary">
          Close
        </Button>
      </DialogActions>
    </Dialog>
  </div>
  
  );
}
