import React, { useContext } from "react";
import { HashRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { AuthContext } from "../context/AuthContext";
import Login from "../components/Login";
import ProtectedRoute from "./ProtectedRoute";
import AddItem from "../pages/AddItem";
import Layout from "../pages/Layout";
import EditItems from "../pages/EditItem";
import OrderPage from "../pages/OrderPage";
import PaymentsPage from "../pages/payment";
import MeetingOrder from "../pages/MeetingOrders";

const AppRoutes = () => {
  const { user } = useContext(AuthContext);

  return (
    <Router>
      <Routes>

        <Route path="/" element={user ? <Navigate to="/order/Beverage" /> : <Login />} />

        <Route element={<Layout />}>
          <Route
            path="/add-item"
            element={
              <ProtectedRoute>
                <AddItem />
              </ProtectedRoute>
            }
          />
          <Route
            path="/order/:category"
            element={
              <ProtectedRoute>
                <OrderPage />
              </ProtectedRoute>
            }
          />
          <Route
            path="/view-items"
            element={
              <ProtectedRoute>
                <EditItems />
              </ProtectedRoute>
            }
          />
          <Route
            path="/payments"
            element={
              <ProtectedRoute>
                <PaymentsPage />
              </ProtectedRoute>
            }
          />
            <Route
            path="/meeting-order"
            element={
              <ProtectedRoute>
                <MeetingOrder />
              </ProtectedRoute>
            }
          />
        </Route>
      </Routes>
    </Router>
  );
};

export default AppRoutes;
