import React, { useEffect, useState } from 'react';
import {
  AppBar,
  Avatar,
  BottomNavigation,
  BottomNavigationAction,
  Box,
  Container,
  Grid,
  Toolbar,
  Typography,
  Button,
  Snackbar,
  Switch,
  Badge,
  FormControlLabel,IconButton ,useTheme,useMediaQuery
} from "@mui/material";
import {
  Coffee,
  FreeBreakfast,
  AddCircle,
  
  Fastfood,
} from "@mui/icons-material";

import RestaurantIcon from '@mui/icons-material/Restaurant';
import { Outlet, useNavigate } from "react-router-dom";
import { db, collection, query, where, onSnapshot,  doc ,writeBatch} from "../firebase/firebaseConfig";
import dayjs from "dayjs";
import { motion, AnimatePresence } from "framer-motion"; 
import { Timestamp } from "firebase/firestore";

import { AuthContext } from "../context/AuthContext";
import { useContext } from "react";
import LogoutIcon from "@mui/icons-material/Logout";
import "../css/home.css";
export default function Home() {

  const theme = useTheme();
  const userData = JSON.parse(localStorage.getItem("authUser"))

const isSmallScreen = useMediaQuery(theme.breakpoints.down('sm'));
  const [openModal, setOpenModal] = useState(false);
  const handleOpenModal = () => setOpenModal(true);
  const handleCloseModal = () => setOpenModal(false);
  const [footerValue, setFooterValue] = useState(() => {
    return localStorage.getItem("footerValue") || "/order/Beverage";
  });

  useEffect(() => {
    localStorage.setItem("footerValue", footerValue);
  }, [footerValue]);
  const [orderCounts, setOrderCounts] = useState({
    Beverage: 0,
    Breakfast: 0,
    Lunch: 0,
    Snacks: 0,
  });
  const { user, logout } = useContext(AuthContext);
  const handleLogout = () => {
    logout();
    navigate("/"); // Redirect to login page
  };

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState("");
  const navigate = useNavigate();

  const [voiceNotification, setVoiceNotification] = useState(
    () => JSON.parse(localStorage.getItem("voiceNotification")) || false
  );

  // ✅ Ensure persistence in localStorage
  useEffect(() => {
    localStorage.setItem("voiceNotification", JSON.stringify(voiceNotification));
  }, [voiceNotification]);

  useEffect(() => {
    const todayStart = Timestamp.fromDate(dayjs().startOf("day").toDate());
    const todayEnd = Timestamp.fromDate(dayjs().endOf("day").toDate());
  
    const q = query(
      collection(db, "orders"),
      where("timestamp", ">=", todayStart),
      where("timestamp", "<=", todayEnd)
    );
  
    const unsubscribe = onSnapshot(q, async (snapshot) => {
      const categoryCounts = { Beverage: 0, Breakfast: 0, Lunch: 0, Snacks: 0 };
      const batch = writeBatch(db);
      
      let newOrderMessage = "";
      let quantityUpdateMessage = "";
      let cancelOrderMessage = "";
  
      let newOrderSnackbar = false;
      let quantityUpdateSnackbar = false;
      let cancelOrderSnackbar = false;
  
      for (const docSnap of snapshot.docs) {
        const data = docSnap.data();
        const orderId = docSnap.id;
  
        const orderItems = Array.isArray(data.orderItems) ? data.orderItems : [];
        let shouldUpdate = false;
        
        let newOrderItems = [];
        let quantityUpdatedItems = [];
        let canceledOrderItems = [];
  
        const updatedOrderItems = orderItems.map((item) => {
          let itemText = translateItemNameToHindi(item.itemName);

          if (item.statusCode === 0 ) {
            categoryCounts[item.catName] = (categoryCounts[item.catName] || 0) + 1;
            // newOrderItems.push(itemText);
            // shouldUpdate = true;
          } 
          if (item.statusCode === 0 && !data.notificationSent) {
            // categoryCounts[item.catName] = (categoryCounts[item.catName] || 0) + 1;
            newOrderItems.push(itemText);
            shouldUpdate = true;
          } 
          
          if (item.statusCode === 0 &&item.orderqty) {
            let qtyText = `${itemText} (${item.quantity})`;
            quantityUpdatedItems.push(qtyText);
            item.orderqty = false;
            shouldUpdate = true;
          }
  
          // **Order Cancellation Handling**
          if (item.statusCode === 2 && item.orderCancelStatus) {
            let cancelText = `${itemText} `;
            canceledOrderItems.push(cancelText);
            item.orderCancelStatus = false;
            shouldUpdate = true;
          }
  
          return item;
        });
  
        if (shouldUpdate) {
          batch.update(doc(db, "orders", orderId), {
            orderItems: updatedOrderItems,
            notificationSent: true,
          });
  
          // **New Order Notification**
          if (newOrderItems.length > 0) {
            newOrderMessage = `${data.userName} ने ${newOrderItems.join(", ")} का नया ऑर्डर दिया है।`;
            newOrderSnackbar = true;
            if (voiceNotification) announceNewOrder(data.userName, newOrderItems.join(", "));
          }
  
          // **Order Quantity Update Notification**
          if (quantityUpdatedItems.length > 0) {
            quantityUpdateMessage = `${data.userName} ने ${quantityUpdatedItems.join(", ")} की मात्रा को अपडेट किया है।`;
            quantityUpdateSnackbar = true;
            if (voiceNotification) announceQuantityUpdate(data.userName, quantityUpdatedItems.join(", "));
          }
  
          // **Order Cancellation Notification**
          if (canceledOrderItems.length > 0) {
            cancelOrderMessage = `${data.userName} ने ${canceledOrderItems.join(", ")} ऑर्डर को रद्द कर दिया है।`;
            cancelOrderSnackbar = true;
            if (voiceNotification) announceCanceledOrder(data.userName, canceledOrderItems.join(", "));
          }
        }
      }
  
      await batch.commit();
      setOrderCounts(categoryCounts);
  
      // Show Snackbar Notifications
      if (newOrderSnackbar) {
        setSnackbarMessage(newOrderMessage);
        setSnackbarOpen(true);
      }
  
      if (quantityUpdateSnackbar) {
        setSnackbarMessage(quantityUpdateMessage);
        setSnackbarOpen(true);
      }
  
      if (cancelOrderSnackbar) {
        setSnackbarMessage(cancelOrderMessage);
        setSnackbarOpen(true);
      }
    });
  
    return () => unsubscribe();
  }, [voiceNotification]);
  
  
  const announceNewOrder = (userName, items) => {
    const message = `${userName} ने ${items} का नया ऑर्डर दिया है।`;
    speak(message);
  };
  
  const announceQuantityUpdate = (userName, items) => {
    const message = `${userName} ने ${items} की मात्रा को अपडेट किया है।`;
    speak(message);
  };
  
  const announceCanceledOrder = (userName, items) => {
    const message = `${userName} ने ${items} ऑर्डर को रद्द कर दिया है।`;
    speak(message);
  };
  
  const speak = (text) => {
    const speech = new SpeechSynthesisUtterance(text);
    speech.lang = "hi-IN"; // Hindi Language
    speech.rate = 1;
    window.speechSynthesis.speak(speech);
  };
  
  const translateItemNameToHindi = (itemName) => {
    const translations = {
      "Coffee": "कॉफी",
      "Tea": "चाय",
      "Thali":"दोपहर का भोजन",

      // ... more translations
    };
    return translations[itemName] || itemName; 
  };




  const handleNavigate = (path) => {
    setFooterValue(path);
    navigate(path);
  };

  return (
    <Container maxWidth="lg" className="home-container">
<AppBar position="fixed" sx={{ backgroundColor: "#ff996d", p: 0.5 }}>
  <Toolbar>
    <Grid container alignItems="center" justifyContent="space-between" direction={isSmallScreen ? 'row' : 'row'}>
      <Grid item sx={{ display: "flex", alignItems: "center", mb: isSmallScreen ? 1 : 0 }}>
        <Avatar src="https://raw.githubusercontent.com/Rohitastronic123/Canteen2.O/refs/heads/gh-pages/mainlogo.png" alt="IOCL Logo" sx={{ width: 55, height: 55 }} />
        <Typography variant="h6" sx={{ fontWeight: "bold", color: "#3f51b5", ml: 2 }}>
          RSO Canteen Services
        </Typography>
      </Grid>


    </Grid>
  </Toolbar>
</AppBar>
<Box sx={{ mt:10, p: 0 ,width:'-webkit-fill-available',display:'flex',ml:'5px'}}>
  
<FormControlLabel
          control={
            <Switch
              checked={voiceNotification}
              onChange={() => setVoiceNotification((prev) => !prev)}
            />
            
          }
          label="Voice Notification"
        />
         </Box>
      <Box sx={{ mt: 0, mb: 7, p: 0 ,width:'-webkit-fill-available'}}>
        <Outlet />
      </Box>

      <Snackbar open={snackbarOpen} autoHideDuration={4000} onClose={() => setSnackbarOpen(false)} message={snackbarMessage} />

  <BottomNavigation
      value={footerValue}
      onChange={(event, newValue) => handleNavigate(newValue)}
      sx={{
        position: "fixed",
        bottom: 0,
        width: "100%",
        backgroundColor: "#fff",
        boxShadow: "0 -2px 5px rgba(0,0,0,0.1)"
      }}
    >
      <BottomNavigationAction
        label="Beverage"
        value="/order/Beverage"
        icon={<Badge badgeContent={orderCounts.Beverage} color="error" showZero><Coffee /></Badge>}
        onClick={() => handleNavigate("/order/Beverage")}
      />
      <BottomNavigationAction
        label="Breakfast"
        value="/order/Breakfast"
        icon={<Badge badgeContent={orderCounts.Breakfast} color="error" showZero><FreeBreakfast /></Badge>}
        onClick={() => handleNavigate("/order/Breakfast")}
      />
      <BottomNavigationAction
        label="Add"
        icon={<AddCircle />}
        onClick={handleOpenModal}
      />
      <BottomNavigationAction
        label="Lunch"
        value="/order/Lunch"
        icon={<Badge badgeContent={orderCounts.Lunch} color="error" showZero><RestaurantIcon /></Badge>}
        onClick={() => handleNavigate("/order/Lunch")}
      />
      <BottomNavigationAction
        label="Snacks"
        value="/order/Snacks"
        icon={<Badge badgeContent={orderCounts.Snacks} color="error" showZero><Fastfood /></Badge>}
        onClick={() => handleNavigate("/order/Snacks")}
      />
    </BottomNavigation>

      <AnimatePresence>
        {openModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="modal-backdrop" // Give it a class for styling
            onClick={handleCloseModal}
            style={{
              position: 'fixed',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              backgroundColor: 'rgba(0, 0, 0, 0.5)',
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              zIndex: 1000, // Ensure it's on top
            }}
          >
            <motion.div
              initial={{ y: 50, opacity: 0, scale: 0.8 }}
              animate={{ y: 0, opacity: 1, scale: 1 }}
              exit={{ y: 50, opacity: 0, scale: 0.8 }}
              transition={{ duration: 0.3, ease: 'easeOut' }}
              className="modal-content"
              style={{
                backgroundColor: '#fff',
                padding: '20px',
                borderRadius: '10px',
                width: '90%', 
                maxWidth: '400px', 
                boxSizing: 'border-box', 
              }}
            >
              <Typography variant="h6" sx={{ mb: 2, textAlign: 'center' }}>
                Choose an Options
              </Typography>
              {(userData?.role === 1 || userData?.role === 2) && (
  <Button
    variant="contained"
    color="primary"
    fullWidth
    sx={{ mb: 2 }}
    onClick={() => handleNavigate('/add-item')}
  >
    Add Item
  </Button>
)}

{(userData?.role === 1 || userData?.role === 2 || userData?.role === 3) && (
  <Button
    variant="contained"
    color="secondary"
    fullWidth
    sx={{ mb: 2 }}
    onClick={() => handleNavigate('/view-items')}
  >
    View Items
  </Button>
)}

{userData?.role === 1 && (
  <Button
    variant="contained"
    color="success"
    fullWidth
    onClick={() => handleNavigate('/payments')}
  >
    Payments
  </Button>
)}
   {/* {(userData?.role === 1 || userData?.role === 2) && (
  <Button
    variant="contained"
    color="primary"
    fullWidth
    sx={{ mt: 2 }}
    onClick={() => handleNavigate('/meeting-order')}
  >
    Meetings Orders
  </Button>
)} */}


            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </Container>
  );
}
