import React, { createContext, useState, useEffect } from "react";
import { db, getDoc, doc } from "../firebase/firebaseConfig";

const AuthContext = createContext();

const AuthProvider = ({ children }) => {
  const [role, setRole] = useState(null);
  const [user, setUser] = useState(() => JSON.parse(localStorage.getItem("authUser")) || null);
  const [isTokenValidated, setIsTokenValidated] = useState(false);

  const validateToken = async (storedUser) => {
    if (!storedUser || !storedUser.uid || isTokenValidated) return;
    try {
      const userDoc = await getDoc(doc(db, "users", storedUser.uid));
      
      if (userDoc.exists()) {
        const userData = userDoc.data();
        // console.log(userDoc.data())
        setRole(userData.roleID);
        if (userData.token === storedUser.token && userData.roleID === storedUser.role) {
          setUser(storedUser);
        } else {
          // console.log(userDoc.data())
          console.warn("Token mismatch! Logging out user.");
          logout();
        }
      } else {
        console.log(userDoc.data())
        console.warn("User not found in Firestore. Logging out.");
        logout();
      }
    } catch (error) {
      console.error("Error validating token:", error);
      logout();
    }
    setIsTokenValidated(true);
  };

  const login = (userData) => {
    localStorage.setItem("authUser", JSON.stringify(userData));
    setUser(userData);
  };

  const logout = () => {
    localStorage.removeItem("authUser");
    setUser(null);
    setIsTokenValidated(false);
  };

  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("authUser"));
    if (storedUser && !isTokenValidated) {
      validateToken(storedUser);
    }
  }, [isTokenValidated]);

  return <AuthContext.Provider value={{ user, role, login, logout }}>{children}</AuthContext.Provider>;
};

export { AuthContext, AuthProvider };
